package com.example.smartpantry.ui;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import com.example.smartpantry.data.PantryDbHelper;import com.example.smartpantry.model.Models.PantryItem;import java.util.*;

public class MainActivity extends Activity {
 PantryDbHelper db; LinearLayout root; ListView list; ArrayList<PantryItem> items; PantryAdapter adapter;
 public void onCreate(Bundle b){super.onCreate(b);db=new PantryDbHelper(this);build();}
 protected void onResume(){super.onResume();if(db!=null)load();}
 void build(){root=Ui.page(this);root.addView(Ui.title(this,"Smart Pantry"));TextView sub=Ui.label(this,"Use what you have. Waste less.");sub.setTextColor(Ui.green);root.addView(sub);Button add=Ui.button(this,"+  Add ingredient");LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,58);ap.setMargins(24,12,24,12);root.addView(add,ap);add.setOnClickListener(v->startActivity(new Intent(this,AddEditIngredientActivity.class)));list=new ListView(this);list.setDivider(null);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));root.addView(Ui.nav(this,v->{},v->startActivity(new Intent(this,SuggestedRecipesActivity.class)),v->startActivity(new Intent(this,SettingsActivity.class))));setContentView(root);load();}
 void load(){items=new ArrayList<>(db.getPantry());adapter=new PantryAdapter(this,items);list.setAdapter(adapter);if(items.isEmpty())list.setEmptyView(Ui.empty(this,"Your pantry is empty.\nAdd ingredients to unlock recipes."));}
 class PantryAdapter extends BaseAdapter{Context c;ArrayList<PantryItem> a;PantryAdapter(Context c,ArrayList<PantryItem>a){this.c=c;this.a=a;}public int getCount(){return a.size();}public Object getItem(int p){return a.get(p);}public long getItemId(int p){return a.get(p).id;}public View getView(int p,View v,android.view.ViewGroup parent){PantryItem x=a.get(p);LinearLayout card=new LinearLayout(c);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(24,16,24,12);card.setBackground(Ui.round(Color.WHITE,18));TextView n=new TextView(c);n.setText(x.name);n.setTextSize(18);n.setTextColor(Ui.text);n.setTypeface(null,1);TextView q=new TextView(c);q.setText(x.quantity+" "+x.unit+(x.expiry.isEmpty()?"":"  ·  expires "+x.expiry));q.setTextColor(Color.DKGRAY);card.addView(n);card.addView(q);card.setOnClickListener(z->{Intent i=new Intent(MainActivity.this,AddEditIngredientActivity.class);i.putExtra("id",x.id);startActivity(i);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,82);lp.setMargins(16,6,16,6);card.setLayoutParams(lp);return card;}}
}
